import { createAudioPlayer, setAudioModeAsync } from 'expo-audio';
import * as Haptics from 'expo-haptics';
import { Platform } from 'react-native';

// Perspective's own chime (generated by scripts/generate-connected-chime.mjs; no third-party audio).
const CHIME: number = require('../../assets/sounds/connected.wav');

/**
 * The sound and vibration for the "you're connected" moment. The chime follows the phone's silent
 * switch. Failures are logged and never block the screen (for example a browser that blocks audio).
 */
export async function playConnectedMoment(): Promise<void> {
  if (Platform.OS !== 'web') {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch((err: unknown) =>
      console.warn('Connected haptic failed', err),
    );
  }
  try {
    await setAudioModeAsync({ playsInSilentMode: false });
    const player = createAudioPlayer(CHIME);
    const release = setTimeout(() => player.remove(), 3000);
    player.addListener('playbackStatusUpdate', (status) => {
      if (status.didJustFinish) {
        clearTimeout(release);
        player.remove();
      }
    });
    player.play();
  } catch (err) {
    console.warn('Connected chime failed', err);
  }
}
